sed -i '/<style>/a \      * { -webkit-tap-highlight-color: transparent; box-sizing: border-box; }\n      *:focus { outline: none; }\n      button { -webkit-appearance: none; background: none; border: none; color: inherit; font: inherit; cursor: pointer; }\n      input, textarea, select { -webkit-appearance: none; font: inherit; }\n      body { -webkit-user-select: none; user-select: none; -webkit-touch-callout: none; }\n      input, textarea, [contenteditable] { -webkit-user-select: text; user-select: text; }' index.html
